actions.script:
const ran = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'get#InboxData', parameters: {}}).call() || {}
const out = ran.result || {}
// mailboxes, the Internal account and its views are an app's: offered when an app answers the Inbox
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {accountList: out.accountList, internalEmailAccountId: out.internalEmailAccountId,
    mailboxesAvailable: !!ran.source, mailboxList: out.mailboxList || [], searchList: out.searchList, totals: out.totals, me: out.me, prefs: out.prefs, failedParts: out.failedParts,
    outOfOfficeList: out.outOfOfficeList})

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'find#InboxRows', parameters: {view: view || null, emailAccountId: account || null,
    emailFolderId: folder || null, emailLabelId: label || null, contactListId: mailbox || null, searchText: q || null,
    unreadOnly: String(unreadOnly) === 'true', cursor: cursor || null, pageSize: pageSize ? Number(pageSize) : 50}}).call()?.result || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {threadList: out.threadList, hasMore: out.hasMore, nextCursor: out.nextCursor,
    storeList: out.storeList, failedStores: out.failedStores, termList: out.termList, conversationView: out.conversationView})

const seq = afterSeq != null && afterSeq !== '' ? Number(afterSeq) : NaN
const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'get#MailChanges', parameters: {
    afterSeq: Number.isNaN(seq) ? null : seq, limit: Number(limit) > 0 ? Number(limit) : 200}}).call()?.result || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : out.unsupported ? {unsupported: true, changes: [], lastSeq: null, more: false, reset: false}
    : {changes: out.changes || [], lastSeq: out.lastSeq, more: out.more === true, reset: out.reset === true,
        uncoveredStores: out.uncoveredStores || []})

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'save#MessageFiles', parameters: {store: store || '', id: id || null,
    emailMessageId: emailMessageId || null, communicationEventId: communicationEventId || null, driveId: driveId || '', path: path || ''}})
        .requireNewTransaction(true).call()?.result || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {savedList: out.savedList, failedList: out.failedList})

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'get#MessageAttachment', parameters: {store: store || '', id: id || ''}}).call()?.result || {}
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.location, String(inline) === 'true' && out.inlineAllowed)

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'get#ContactCard', parameters: {emailAddress: emailAddress || null,
    partyId: partyId || null, name: name || null}}).call()?.result || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {card: out.card})

const list = (text) => text ? String(text).split(',').map((id) => id.trim()).filter((id) => id) : []
const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'set#ThreadState', parameters: {targetsJson: targetsJson || '[]', action: action || '',
    snoozedThruDate: snoozedThruDate ? new Date(Number(snoozedThruDate)) : null, emailFolderId: emailFolderId || null,
    addLabelIdList: list(addLabelIds), removeLabelIdList: list(removeLabelIds), clientRef: clientRef || null}}).call()?.result || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {updatedCount: out.updatedCount, failedList: out.failedList, doneKeys: out.doneKeys,
    duplicate: out.duplicate === true})

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'link#ThreadRecord', parameters: {emailMessageId: emailMessageId || null,
    communicationEventId: communicationEventId || null, recordEntityName: recordEntityName || '', recordId: recordId || ''}}).call()?.result || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {communicationEventId: out.communicationEventId, created: out.created, link: out.link,
    messageInfos: [{type: 'success', message: ec.l10n.localize('Linked') + (out.link ? ': ' + out.link.title : ''), link: out.link?.url || null,
        linkText: ec.l10n.localize('Open')}]})

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'unlink#ThreadRecord', parameters: {emailMessageId: emailMessageId || null,
    communicationEventId: communicationEventId || null, recordEntityName: recordEntityName || '', recordId: recordId || ''}}).call()?.result || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {unlinked: out.unlinked})

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'prepare#CreateFromMessage', parameters: {kind: kind || '',
    emailMessageId: emailMessageId || null, communicationEventId: communicationEventId || null}}).call()?.result || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {url: out.url, communicationEventId: out.communicationEventId})

const out = ec.service.sync().name('org.moqui.ui.ShellServices.call#Providers').parameters({hook: 'create-from', mutation: true,
    parameters: {kind: kind || '', emailMessageId: emailMessageId || null, communicationEventId: communicationEventId || null}}).call()
const made = (out?.results || []).find((result) => result.recordId) || {}
if (!ec.message.hasError() && out?.unavailable) ec.message.addError(ec.l10n.localize('Nothing here makes records from messages'))
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {recordEntityName: made.recordEntityName, recordId: made.recordId, url: made.url,
    messageInfos: [{type: 'success', message: made.message || ec.l10n.localize('Made'), link: made.url || null,
        linkText: ec.l10n.localize('Open')}]})

const out = ec.service.sync().name('org.moqui.comms.InboxServices.store#TrustedSender').parameters({emailAddress: emailAddress || '',
    remove: String(remove) === 'true'}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {trustedSenders: out.trustedSenders})

const out = ec.service.sync().name('org.moqui.mail.EmailClientServices.unsubscribe#Message').parameter('emailMessageId', emailMessageId || '').call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {method: out.method, unsubscribed: out.unsubscribed, url: out.url,
    messageInfos: out.unsubscribed ? [{type: 'success', message: ec.l10n.localize('Unsubscribed')}] : []})

const out = ec.service.sync().name('org.moqui.mail.EmailClientServices.block#Sender').parameter('emailMessageId', emailMessageId || '').call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {emailRuleId: out.emailRuleId, movedCount: out.movedCount,
    messageInfos: [{type: 'success', message: ec.l10n.localize('Sender blocked: their mail goes to Spam')}]})

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'respond#Invitation', parameters: {emailMessageId: emailMessageId || '',
    response: response || ''}}).call()?.result || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {workEffortId: out.workEffortId, statusId: out.statusId, replySent: out.replySent, eventUrl: out.eventUrl || null,
    messageInfos: [{type: 'success', message: ec.l10n.localize({accept: 'Accepted', tentative: 'Tentative', decline: 'Declined'}[response] || 'Answered'),
        link: out.eventUrl || null, linkText: ec.l10n.localize('Open event')}]})

const out = ec.service.sync().name('org.moqui.mail.EmailClientServices.store#EmailSearch').parameters({emailSearchId: emailSearchId || null,
    searchName: searchName || '', queryText: queryText || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {emailSearchId: out.emailSearchId})

const out = ec.service.sync().name('org.moqui.mail.EmailClientServices.create#EmailLabel').parameters({emailAccountId: emailAccountId || '',
    labelName: labelName || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {emailLabelId: out.emailLabelId})

const out = ec.service.sync().name('org.moqui.mail.EmailClientServices.create#EmailFolder').parameters({emailAccountId: emailAccountId || '',
    folderName: folderName || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {emailFolderId: out.emailFolderId})
